-- ============================================
-- LUMA — Thème 11 : MOYEN 1/3 x4 — Organiser sa journée entre plusieurs concerts
-- ============================================


update scenarios set content = '{"characters": {"theo": "Theo"}, "start_node": "n1", "nodes": {"n1": {"speaker": "theo", "text": "Okay, so both our favorite bands play at 4pm today, but on totally different stages.", "text_fr": "Bon, donc nos deux groupes préférés jouent à 16h aujourd''hui, mais sur des scènes totalement différentes.", "choices": [{"text": "That''s tough. Which one do you want to see more?", "text_fr": "C''est dur. Lequel tu veux voir le plus ?", "next": "n2"}, {"text": "Maybe we split up and each catch our own favorite?", "text_fr": "On pourrait se séparer et chacun voir son préféré ?", "next": "n2b"}]}, "n2": {"speaker": "theo", "text": "Honestly, I''ve been wanting to see the Wild Echoes for years. But I know you love the other one too.", "text_fr": "Honnêtement, ça fait des années que je veux voir les Wild Echoes. Mais je sais que t''aimes bien l''autre aussi.", "choices": [{"text": "Let''s compromise — catch half of each set if the stages aren''t too far apart.", "text_fr": "Trouvons un compromis — voyons la moitié de chaque concert si les scènes sont pas trop loin.", "next": "n3"}, {"text": "You should go see Wild Echoes, I don''t mind missing mine this once.", "text_fr": "Tu devrais aller voir Wild Echoes, ça me dérange pas de rater le mien cette fois.", "next": "n3b"}]}, "n2b": {"speaker": "theo", "text": "That could work, though I''d rather we experience this together, honestly.", "text_fr": "Ça pourrait marcher, même si je préférerais qu''on vive ça ensemble, honnêtement.", "choices": [{"text": "I feel the same way. Let''s find a compromise instead.", "text_fr": "Je ressens pareil. Trouvons un compromis plutôt.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(Checking the festival map) The stages are actually only a five-minute walk apart!", "text_fr": "(En vérifiant le plan du festival) Les scènes ne sont en fait qu''à cinq minutes de marche l''une de l''autre !", "choices": [{"text": "Perfect, let''s catch the start of Wild Echoes, then head to the other stage.", "text_fr": "Parfait, voyons le début de Wild Echoes, puis allons à l''autre scène.", "next": "n4"}]}, "n3b": {"speaker": "theo", "text": "Are you sure? I don''t want you to feel like you''re missing out because of me.", "text_fr": "T''es sûr ? Je veux pas que tu te sentes lésé à cause de moi.", "choices": [{"text": "I''m sure, honestly. Your excitement about this means more to me.", "text_fr": "J''en suis sûr, honnêtement. Ton excitation pour ça compte plus pour moi.", "next": "n4"}]}, "n4": {"speaker": "theo", "text": "This plan sounds perfect actually — best of both worlds!", "text_fr": "Ce plan a l''air parfait en fait — le meilleur des deux mondes !", "choices": [{"text": "Let''s grab a quick snack before heading over, we have a bit of time.", "text_fr": "Prenons une collation rapide avant d''y aller, on a un peu de temps.", "next": "n5"}, {"text": "Let''s head there now to grab a good spot before it gets crowded.", "text_fr": "Allons-y maintenant pour avoir une bonne place avant que ça se remplisse.", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(You both make your way to Wild Echoes'' stage, excitement building with the crowd.)", "text_fr": "(Vous vous dirigez tous les deux vers la scène de Wild Echoes, l''excitation grandissant avec la foule.)", "choices": [{"text": "(Enjoy the first half of the set together, singing along.)", "text_fr": "(Profite de la première moitié du concert ensemble, en chantant.)", "next": "n6"}]}, "n6": {"speaker": "theo", "text": "This is incredible! Okay, should we head to the other stage now?", "text_fr": "C''est incroyable ! Bon, on devrait aller à l''autre scène maintenant ?", "choices": [{"text": "Yes, let''s go now so we don''t miss too much of the other set.", "text_fr": "Oui, allons-y maintenant pour pas rater trop de l''autre concert.", "next": "n7"}, {"text": "Actually, this song is amazing, can we stay just a bit longer?", "text_fr": "En fait, cette chanson est géniale, on peut rester un peu plus longtemps ?", "next": "n7b"}]}, "n7": {"speaker": "you_thought", "text": "(You both hurry to the second stage, arriving just as the second half begins.)", "text_fr": "(Vous vous précipitez tous les deux vers la deuxième scène, arrivant juste au moment où la seconde moitié commence.)", "choices": [{"text": "Perfect timing! Let''s enjoy the rest of this set.", "text_fr": "Timing parfait ! Profitons du reste de ce concert.", "next": "n8"}]}, "n7b": {"speaker": "theo", "text": "Ha, fine, one more song, then we really have to go!", "text_fr": "Ha, d''accord, une chanson de plus, puis on doit vraiment y aller !", "choices": [{"text": "Deal! Then let''s rush over together.", "text_fr": "Marché conclu ! Puis dépêchons-nous d''y aller ensemble.", "next": "n8"}]}, "n8": {"speaker": "theo", "text": "This turned out to be the perfect solution — we got to experience both!", "text_fr": "Ça s''est avéré être la solution parfaite — on a pu profiter des deux !", "choices": [{"text": "Agreed, compromise really was the best plan today.", "text_fr": "D''accord, le compromis était vraiment le meilleur plan aujourd''hui.", "next": "end_bothsets"}]}, "end_bothsets": {"speaker": "theo", "text": "Best festival day ever, honestly. Thanks for figuring this out with me.", "text_fr": "Meilleure journée de festival jamais vécue, honnêtement. Merci d''avoir trouvé ça avec moi.", "end": true, "ending_label": "Journée organisée entre deux concerts avec succès 🎵🗺️"}}}'::jsonb, is_playable = true
where title = 'Organiser sa journée entre plusieurs concerts'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
